package local.generalsmc.client;

import local.generalsmc.nativebridge.*;
import local.generalsmc.GeneralsMod;
import net.minecraft.client.*;
import net.minecraft.client.gui.components.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

/** Follow-up checks against the real remapped player JAR; never distributed to players. */
final class NativeFeedbackBench {
    static int stage,age,stops,oil,jet,woodBefore,airfield;static CompletableFuture<?> work;static com.mojang.blaze3d.platform.InputConstants.Key oldKey;
    static final BlockPos OIL=new BlockPos(30,64,32);static String retired;static UUID portraitMob;
    static void next(int n){stage=n;age=0;GeneralsMod.LOG.info("Feedback case {}",n);}
    static void require(boolean value,String message){if(!value)throw new IllegalStateException(message);}
    static void query(NativeWorldView v)throws Exception{Files.deleteIfExists(v.session.directory.resolve("terrain-extremes-test.json"));var a=v.origin.nativePoint(new Vec3(-15.5,64,12.5));var b=v.origin.nativePoint(new Vec3(-5.5,64,12.5));v.session.send("TEST_TERRAIN_EXTREMES "+a.x+" "+a.y+" "+a.z+" "+b.x+" "+b.y+" "+b.z);}
    static com.google.gson.JsonObject extrema(NativeWorldView v)throws Exception{return com.google.gson.JsonParser.parseString(Files.readString(v.session.directory.resolve("terrain-extremes-test.json"))).getAsJsonObject();}
    static boolean tick(Minecraft mc,List<String> checks)throws Exception{
        age++;var v=NativeWorldView.current;
        if(stage==0){stops=v.state.stopMessages();var screen=(NativeWorldScreen)mc.screen;screen.keyPressed(org.lwjgl.glfw.GLFW.GLFW_KEY_S,31,0);screen.keyReleased(org.lwjgl.glfw.GLFW.GLFW_KEY_S,31,0);next(1);}
        else if(stage==1&&age>30){require(v.state.stopMessages()>stops,"Original Stop did not reach chosen game CommandMap");require(RtsBindings.scan(org.lwjgl.glfw.GLFW.GLFW_KEY_S,31)==31,"Original key was remapped by Minecraft RTS bindings");checks.add("The selected game owns its keyboard commands; actual S reaches the original Stop action without a second Minecraft action map");query(v);next(2);}
        else if(stage==2&&age>25){var result=extrema(v);require(result.get("valid").getAsBoolean()&&Math.abs(result.get("max").getAsDouble())<.1,"Flat terrain query used stock/sparse placeholder heights: "+result);work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);for(int x=-9;x<=-7;x++)for(int y=64;y<=66;y++)l.setBlock(new BlockPos(x,y,12),Blocks.DIRT.defaultBlockState(),3);},mc.getSingleplayerServer());next(3);}
        else if(stage==3&&age>120&&work.isDone()){work.join();query(v);next(4);}
        else if(stage==4&&age>25){var result=extrema(v);require(result.get("valid").getAsBoolean()&&Math.abs(result.get("max").getAsDouble()-3*WorldScale.UNITS_PER_BLOCK)<.1,"Projectile terrain query ignored a real three-block hill: "+result);checks.add("The actual original projectile terrain-extrema function returns flat Minecraft ground and then the exact height of a newly placed three-block hill, instead of the 4096 sparse-cell placeholder");NativeReleaseBench.openSettings(mc);next(41);}
        else if(stage==41&&NativeNetworkClient.rules!=null){for(int i=0;i<2;i++)NativeSetupBench.click(mc.screen,"Радиус разрушения блоков: ×2");for(int i=0;i<3;i++)NativeSetupBench.click(mc.screen,"Пробитие блоков: ×1");next(42);}
        else if(stage==42&&age>30){require(NativeNetworkClient.rules.values().blastRadius()==4&&NativeNetworkClient.rules.values().blastPower()==4,"Block strength settings did not reach server");NativeSetupBench.click(mc.screen,"Готово");NativeRtsController.toggle();work=CompletableFuture.supplyAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);for(int x=-37;x<=-32;x++)for(int z=-8;z<=-3;z++)for(int y=64;y<=67;y++)if(y==67||x==-37||x==-32||z==-8||z==-3)l.setBlock(new BlockPos(x,y,z),Blocks.OAK_PLANKS.defaultBlockState(),3);return wood(mc);},mc.getSingleplayerServer());next(43);}
        else if(stage==43&&work.isDone()&&age>60){woodBefore=(int)work.join();NativeReleaseBench.spawn(v,"AmericaPowerPlant",new Vec3(-24.5,64,16.5));NativeReleaseBench.spawn(v,"AmericaAirfield",new Vec3(24.5,64,-20.5));next(44);}
        else if(stage==44&&age>60){airfield=v.state.objects().stream().filter(a->a.template().equals("AmericaAirfield")&&a.owner()==v.state.localPlayerIndex()).findFirst().orElseThrow().id();v.session.select(airfield);next(441);}
        else if(stage==441&&age>25){((NativeWorldScreen)mc.screen).clickCommand("Command_ConstructAmericaJetRaptor",true);next(442);}
        else if(stage==442&&age>5){((NativeWorldScreen)mc.screen).clickCommand("Command_ConstructAmericaJetRaptor",false);next(443);}
        else if(stage==443){var plane=v.state.objects().stream().filter(a->a.template().equals("AmericaJetRaptor")&&a.owner()==v.state.localPlayerIndex()&&(a.externalKey()==null||a.externalKey().isEmpty())).findFirst().orElse(null);if(plane!=null){jet=plane.id();v.session.select(jet);v.cameraX=-34.5;v.cameraZ=-5.5;next(444);}else require(age<700,"Original Airfield never produced its Raptor");}
        else if(stage==444&&age>30){((NativeWorldScreen)mc.screen).keyPressed(org.lwjgl.glfw.GLFW.GLFW_KEY_LEFT_CONTROL,29,0);next(445);}
        else if(stage==445&&age>20&&v.state.forceAttack()){NativeWorldPolishBench.click((NativeWorldScreen)mc.screen,new Vec3(-34.5,67.1,-5.5));next(45);}
        else if(stage==45){if(age==8)((NativeWorldScreen)mc.screen).keyReleased(org.lwjgl.glfw.GLFW.GLFW_KEY_LEFT_CONTROL,29,0);if(age%20==0)work=CompletableFuture.supplyAsync(()->wood(mc),mc.getSingleplayerServer());if(work.isDone()&&work.join() instanceof Integer remaining&&remaining<woodBefore/2){checks.add("Actual world-settings buttons raise block radius/penetration to four; a Raptor produced by the original Airfield follows its real attack order and destroys over half a Minecraft wooden house");work=CompletableFuture.runAsync(()->mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA).setBlock(OIL,SiteBlocks.OIL.defaultBlockState(),3),mc.getSingleplayerServer());next(5);}else require(age<1000,"Original Raptor attack did not sufficiently damage wood: "+work.join()+"/"+woodBefore+" plane="+v.state.objects().stream().filter(a->a.id()==jet).findFirst());}
        else if(stage==5&&age>120&&work.isDone()){work.join();var site=v.state.sites().stream().filter(s->s.key().equals(WorldSiteStore.key(OIL))).findFirst().orElse(null);if(site==null){require(age<240,"Oil marker never created its source structure");return false;}oil=site.id();require(v.state.objects().stream().anyMatch(a->a.id()==oil&&a.health()>0),"Oil was not alive before retirement test");v.session.send("TEST_DAMAGE "+oil+" 1000000");next(6);}
        else if(stage==6&&age>160){work=CompletableFuture.supplyAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);var store=WorldSiteStore.get(l);var site=store.sites().stream().filter(s->s.key().equals(WorldSiteStore.key(OIL))).findFirst().orElseThrow();require(site.cash()==-2,"Destroyed oil marker was not retired");var tag=store.save(new net.minecraft.nbt.CompoundTag(),l.registryAccess());var list=tag.getList("sites",10);boolean found=false;for(int i=0;i<list.size();i++){var n=list.getCompound(i);if(n.getInt("x")==OIL.getX()&&n.getInt("z")==OIL.getZ()){require(n.getInt("cash")==-2,"Retirement not saved to NBT");found=true;}}require(found,"Retired marker missing from SavedData");var base=v.state.objects().stream().filter(a->a.structure()&&a.health()>0&&a.owner()==v.state.localPlayerIndex()).findFirst().orElseThrow();var proxy=NativeRtsController.combat.actor(base.id());require(proxy!=null&&proxy.canBeCollidedWith(),"Original building has no solid Minecraft presence");var box=proxy.getBoundingBox();var z=new net.minecraft.world.entity.monster.Zombie(net.minecraft.world.entity.EntityType.ZOMBIE,l);z.setNoAi(true);z.setNoGravity(true);z.setPos(box.minX-.35,proxy.getY(),proxy.getZ());l.addFreshEntity(z);z.move(net.minecraft.world.entity.MoverType.SELF,new Vec3(2,0,0));require(z.getBoundingBox().maxX<=box.minX+.001,"Minecraft mob walked through original building collision");require(z.getY()<box.maxY,"Minecraft mob stepped onto original building");z.discard();return "retired";},mc.getSingleplayerServer());next(7);}
        else if(stage==7&&work.isDone()&&age>60){work.join();require(v.state.objects().stream().noneMatch(a->a.id()==oil&&a.health()>0),"Destroyed oil reappeared");checks.add("Destroying an actual marked original oil derrick persists its retirement in world NBT and does not recreate it on subsequent synchronization");checks.add("A real Minecraft Zombie collision move stops at the original building's solid presence and cannot step onto its roof");work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);var slime=new net.minecraft.world.entity.monster.Slime(net.minecraft.world.entity.EntityType.SLIME,l);slime.setNoAi(true);slime.setPersistenceRequired();slime.setSize(4,true);slime.setPos(.5,64,-24.5);portraitMob=slime.getUUID();l.addFreshEntity(slime);},mc.getSingleplayerServer());v.session.select(0);v.cameraX=.5;v.cameraZ=-24.5;next(70);}
        else if(stage==70&&work.isDone()&&age>60){work.join();if(java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).noneMatch(e->e.getUUID().equals(portraitMob))){require(age<160,"Portrait fixture Slime was not tracked by Minecraft before selection");return false;}NativeWorldPolishBench.clickMob(mc,(NativeWorldScreen)mc.screen,portraitMob);next(71);}
        else if(stage==71&&age>30){require(v.state.selected().stream().anyMatch(id->v.state.objects().stream().anyMatch(a->a.id()==id&&portraitMob.toString().equals(a.externalKey()))),"An ordinary Slime could not be selected with LMB");Screenshot.grab(mc.gameDirectory,"95-feedback-mob-icon-only.png",mc.getMainRenderTarget(),c->{});checks.add("An ordinary Slime is selected by a real LMB click with an empty selection and receives the Minecraft entity portrait in the original HUD");NativeRtsController.stop();mc.setScreen(new GeneralsSetupScreen(null));NativeSetupBench.click(mc.screen,"+");require(mc.screen instanceof GeneralsSetupScreen.Connect,"Game-selector plus did not open connection");mc.screen.onClose();mc.setScreen(new GeneralsSetupScreen(null));NativeSetupBench.click(mc.screen,"Управление");NativeSetupBench.click(mc.screen,"Изменить клавиши");require(mc.screen instanceof net.minecraft.client.gui.screens.options.controls.KeyBindsScreen,"Help did not open Minecraft keybindings");checks.add("The game-selector plus opens game connection and the controls screen opens Minecraft keybindings through their real buttons");mc.setScreen(new GeneralsSetupScreen(null));work=language(mc,"en_us");next(8);}
        else if(stage==8&&work.isDone()&&mc.getOverlay()==null){work.join();require(L.s("Начать RTS здесь").equals("Start RTS here"),"English UI lookup failed: "+L.s("Начать RTS здесь"));require(!L.decode(local.generalsmc.LocalText.token("Этот цвет уже занят. Выберите другой или случайный.")).matches(".*[А-Яа-я].*"),"Common-server error stayed Russian in English client");mc.setScreen(new GeneralsSetupScreen(null));next(80);}
        else if(stage==80&&age>15){NativeSetupBench.bounds(mc.screen);Screenshot.grab(mc.gameDirectory,"93-feedback-english-menu.png",mc.getMainRenderTarget(),c->{});checks.add("A real English resource reload translates menus and server-origin errors; Russian is selected only by the client's language");work=language(mc,"ru_ru");next(9);}
        else if(stage==9&&work.isDone()&&age>25){work.join();mc.setScreen(new GeneralsSetupScreen(null));NativeSetupBench.click(mc.screen,"Сетевая схватка / NPC");NativeSetupBench.click(mc.screen,"Создать комнату");next(10);}
        else if(stage==10&&NativeNetworkClient.lobby!=null&&!NativeNetworkClient.lobby.preparing()&&NativeNetworkClient.lobby.members().stream().allMatch(NativeNetworkServer.Member::ready)){work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);var p=new BlockPos(-40,64,-40);l.setBlock(p,SiteBlocks.START.defaultBlockState(),3);},mc.getSingleplayerServer());next(11);}
        else if(stage==11&&work.isDone()&&age>40){work.join();NativeSetupBench.click(mc.screen,"+ Добавить NPC");next(12);}
        else if(stage==12&&age>30){var lobby=NativeNetworkClient.lobby;var npc=lobby.starts().stream().filter(s->s.difficulty()>=0).findFirst().orElseThrow();require(npc.faction().isEmpty()&&npc.color()==-1,"New NPC did not offer random faction/color");var button=mc.screen.children().stream().filter(b->b instanceof CycleButton c&&c.getMessage().getString().equals("Сложность: средняя")).map(b->(CycleButton)b).findFirst().orElseThrow();mc.screen.mouseScrolled(0,0,0,-20);button=mc.screen.children().stream().filter(b->b instanceof CycleButton c&&c.getMessage().getString().equals("Сложность: средняя")).map(b->(CycleButton)b).findFirst().orElseThrow();button.mouseClicked(button.getX()+5,button.getY()+5,1);next(13);}
        else if(stage==13&&age>30){require(NativeNetworkClient.lobby.starts().stream().anyMatch(s->s.difficulty()==0),"RMB did not reverse NPC difficulty");require(!NativeDebugScreen.available(),"Local debug tools became available in shared lobby");NativeSetupBench.bounds(mc.screen);Screenshot.grab(mc.gameDirectory,"94-feedback-russian-lobby.png",mc.getMainRenderTarget(),c->{});checks.add("Real lobby buttons add a random-side NPC and reverse its difficulty on RMB; local creative debug tools are unavailable in the shared room");NativeNetworkClient.leave();return true;}
        return false;
    }
    static int wood(Minecraft mc){var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);int count=0;for(int x=-37;x<=-32;x++)for(int z=-8;z<=-3;z++)for(int y=64;y<=67;y++)if(l.getBlockState(new BlockPos(x,y,z)).is(Blocks.OAK_PLANKS))count++;return count;}
    static CompletableFuture<Void> language(Minecraft mc,String code){mc.getLanguageManager().setSelected(code);mc.options.languageCode=code;return mc.reloadResourcePacks();}
}
